import { useCallback, useEffect, useRef, useState } from 'react';
import { ArrowLeft, ArrowRight, Bell, BookOpen, Check, CheckCheck, CheckCircle2, ChevronDown, Clock3, FileCheck2, FileText, GraduationCap, HelpCircle, Languages, LayoutDashboard, ListChecks, Loader2, LockKeyhole, LogOut, MessageCircle, Plus, RefreshCw, Send, ShieldCheck, Sparkles, Upload, UserRound, Users, X } from 'lucide-react';
import type { ReactNode } from 'react';
import { api, ApiError } from './api_接口';
import type { Account, Detail, HelpCase, Lang, MatchStatus, Notice, Profile, Scope, Source, Task } from './types_类型';
import { dateLabel, fieldLabel, label, localize, tr, valueLabel } from './i18n_双语';
import AuthPanel from './AuthPanel_登录注册';
import type { AuthForm, AuthMode } from './AuthPanel_登录注册';

const icons:Record<string,typeof CheckCircle2>={conditions_met:CheckCircle2,conditions_not_met:X,missing_information:HelpCircle,needs_staff_review:MessageCircle,requires_reconfirmation:RefreshCw,done:CheckCheck};
function Badge({status,lang}:{status:string;lang:Lang}){const Icon=icons[status]??Clock3;return <span className={`badge ${status}`}><Icon size={14}/>{label(status,lang)}</span>;}
function Empty({children}:{children:ReactNode}){return <div className="empty"><BookOpen size={32}/><p>{children}</p></div>;}
function Loading({lang}:{lang:Lang}){return <div className="loading"><Loader2 className="spin" size={24}/>{tr(lang,'불러오는 중…','正在加载…')}</div>;}
function Field({title,hint,children}:{title:string;hint?:string;children:ReactNode}){return <label className="field"><span>{title}</span>{children}{hint&&<small>{hint}</small>}</label>;}
const categoryLabel=(category:string,lang:Lang)=>({scholarship:tr(lang,'장학금','奖学金'),dormitory:tr(lang,'기숙사','宿舍'),activity:tr(lang,'교내 활동','校内活动')}[category]??category);
const scopeLabel=(scope:Scope,lang:Lang)=>({none:tr(lang,'공유하지 않음','不共享'),case_only:tr(lang,'이 문의만 공유','仅共享这个案例'),tasks_and_cases:tr(lang,'관련 진행 + 문의 공유','共享相关任务进度和案例')}[scope]);
const applicationStatus=(value:unknown):string=>typeof value==='string'?value:(value as {status?:string}|null)?.status??'unknown';
const detailTabs=[['tasks','실행계획','行动清单'],['evidence','조건과 원문','条件与原文'],['versions','변경 이력','版本变化'],['help','도움 요청','请求协助']];

export default function App(){
  const [lang,setLang]=useState<Lang>(()=>localStorage.getItem('campus-lang')==='zh'?'zh':'ko');
  const [account,setAccount]=useState('');const [personalAccount,setPersonalAccount]=useState<Account|null>(null);
  const [sessionChecking,setSessionChecking]=useState(true);const [authMode,setAuthMode]=useState<AuthMode>('demo');const identityRef=useRef('');
  const [accounts,setAccounts]=useState<Account[]>([]);const [health,setHealth]=useState<{mode?:string;demo_time?:string;real_mode_available?:boolean}>({});
  const [page,setPage]=useState('notices');const [notices,setNotices]=useState<Notice[]>([]);const [profile,setProfile]=useState<Profile|null>(null);const [cases,setCases]=useState<HelpCase[]>([]);
  const [selected,setSelected]=useState<string|null>(null);const [detail,setDetail]=useState<Detail|null>(null);const [detailTab,setDetailTab]=useState('tasks');
  const [loading,setLoading]=useState(false);const [busy,setBusy]=useState(false);const [error,setError]=useState('');const [feedback,setFeedback]=useState('');
  const [filter,setFilter]=useState('all');const [sources,setSources]=useState<Source[]>([]);const [sourceText,setSourceText]=useState('');const [sourceUrl,setSourceUrl]=useState('');const [extractMode,setExtractMode]=useState('demo');
  const [editor,setEditor]=useState('');const [staffDraft,setStaffDraft]=useState<Notice|null>(null);const [staffVersion,setStaffVersion]=useState(1);
  const staff=account==='staff'||account==='other_staff';const isDemo=personalAccount===null;const t=(ko:string,zh:string)=>tr(lang,ko,zh);const l=(value:unknown)=>localize(value,lang);
  useEffect(()=>{document.documentElement.lang=lang==='ko'?'ko':'zh-CN';localStorage.setItem('campus-lang',lang);},[lang]);
  useEffect(()=>{api<Account[]>('A','/accounts').then(setAccounts).catch(e=>setError(e.message));api<typeof health>('A','/health').then(setHealth).catch(()=>{});},[]);
  useEffect(()=>{
    let active=true;
    (async()=>{try{const result=await api<{account:Account|null}>('','/auth/me');if(!active)return;
      if(result.account)enterAccount(result.account.id,result.account);
      else{const stored=localStorage.getItem('campus-account')??'';enterAccount(['A','B','C','staff','other_staff'].includes(stored)?stored:'');}
    }catch(e){if(active){if(e instanceof ApiError&&e.status===401){enterAccount('');setAuthMode('login');}setError((e as Error).message);}}finally{if(active)setSessionChecking(false);}})();
    return()=>{active=false;};
  },[]);
  useEffect(()=>{const expire=()=>{enterAccount('');setAuthMode('login');setError(t('로그인이 만료되었습니다. 다시 로그인하거나 데모 계정을 선택해 주세요.','登录已失效，请重新登录或选择演示账号。'));};window.addEventListener('uniaction-session-expired',expire);return()=>window.removeEventListener('uniaction-session-expired',expire);},[lang]);
  const load=useCallback(async()=>{
    if(!account||sessionChecking)return;const requestedAccount=account;setLoading(true);setError('');
    try{const [nextNotices,nextCases]=await Promise.all([api<Notice[]>(account,'/notices'),api<HelpCase[]>(account,'/cases')]);if(identityRef.current!==requestedAccount)return;setNotices(nextNotices);setCases(nextCases);if(!staff){const nextProfile=await api<Profile>(account,'/profile');if(identityRef.current===requestedAccount)setProfile(nextProfile);}else{const nextSources=await api<Source[]>(account,'/demo/sources');if(identityRef.current===requestedAccount)setSources(nextSources);}}
    catch(e){if(identityRef.current===requestedAccount)setError((e as Error).message);}finally{if(identityRef.current===requestedAccount)setLoading(false);}
  },[account,staff,sessionChecking]);
  useEffect(()=>{load();},[load]);
  const loadDetail=useCallback(async(id:string)=>{const requestedAccount=account;const result=await api<Detail>(account,`/notices/${id}`);if(identityRef.current===requestedAccount)setDetail({...result,tasks:result.tasks??[],versions:result.versions??[]});return result;},[account]);
  useEffect(()=>{if(selected){setDetail(null);setError('');loadDetail(selected).catch(e=>{if(identityRef.current===account)setError(e.message);});}},[selected,loadDetail,account]);
  async function run(action:()=>Promise<unknown>,success?:string){const requestedAccount=identityRef.current;setBusy(true);setError('');setFeedback('');try{await action();if(identityRef.current!==requestedAccount)return;if(success)setFeedback(success);await load();if(selected&&identityRef.current===requestedAccount)await loadDetail(selected);}catch(e){if(identityRef.current===requestedAccount)setError((e as Error).message);}finally{if(identityRef.current===requestedAccount)setBusy(false);}}
  function enterAccount(id:string,identity:Account|null=null){identityRef.current=id;setPersonalAccount(identity);setNotices([]);setCases([]);setProfile(null);setAccount(id);if(identity)localStorage.removeItem('campus-account');else if(id)localStorage.setItem('campus-account',id);else localStorage.removeItem('campus-account');setPage('notices');setSelected(null);setDetail(null);setStaffDraft(null);setFilter('all');setFeedback('');setError('');setLoading(false);setBusy(false);}
  async function login(id:string){setBusy(true);setError('');try{await api(account,'/auth/logout','POST',{});enterAccount(id);if(!id)setAuthMode('demo');}catch(e){setError((e as Error).message);}finally{setBusy(false);}}
  async function submitAuth(data:AuthForm){setBusy(true);setError('');try{const result=await api<{account:Account}>('',authMode==='register'?'/auth/register':'/auth/login','POST',data);enterAccount(result.account.id,result.account);if(authMode==='register'){setPage('profile');setFeedback(t('개인 계정을 만들었습니다. 필요한 학생 정보를 추가해 주세요.','个人账号已创建，请按需要补充学生资料。'));}}catch(e){setError((e as Error).message);}finally{setBusy(false);}}
  function navigate(target:string){setPage(target);setSelected(null);setDetail(null);setError('');setFeedback('');}
  function openNotice(id:string,tab='tasks'){setSelected(id);setDetailTab(tab);setFeedback('');}
  async function openEditor(notice:Notice,version=notice.version){await run(async()=>{const full=await api<Notice>(account,`/notices/${notice.id}/versions/${version}`);setStaffDraft(full);setStaffVersion(version);setEditor(JSON.stringify(full,null,2));setPage('review');setSelected(null);});}
  async function createManual(){
    const preserved=sourceText||'[가상 데모 공지 / 虚构演示通知]\n지원 조건은 담당자가 확인합니다. / 条件需要工作人员确认。';
    const digest=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(preserved));
    const hash=Array.from(new Uint8Array(digest)).map(x=>x.toString(16).padStart(2,'0')).join('');
    setStaffDraft(null);setStaffVersion(1);
    setEditor(JSON.stringify({id:'MANUAL-1',school_id:accounts.find(a=>a.id===account)?.school_id??'hanyang_demo',title:{ko:'수동 공지',zh:'手工通知'},category:'activity',source_url:sourceUrl||'https://demo.invalid/manual',source_text:preserved,source_hash:hash,version:1,publication_status:'draft',reviewed_by:null,reviewed_at:null,eligibility_rules:{op:'needs_staff_review',field:null,value:null,children:[],evidence:preserved},required_documents:[],official_deadline:null,application_window:{opens_at:null,closes_at:null},application_url:null,application_link_type:'unknown',office_contact:null,task_templates:[],evidence:{},ambiguities:[{ko:'중요 조건과 자료, 날짜를 원문에서 확인해야 합니다.',zh:'需要按原文确认重要条件、材料和日期。'}],change_summary:{ko:'수동 초안',zh:'人工草稿'},extraction_mode:'manual'},null,2));setPage('review');
  }
  function switchLanguage(){setFeedback('');setError('');setLang(lang==='ko'?'zh':'ko');}

  const languageButton=<button className="language" onClick={switchLanguage} aria-label={t('中文로 전환','切换韩文')}><Languages size={16}/>{lang==='ko'?'中文':'한국어'}</button>;
  const noticeCounts=(status:MatchStatus)=>notices.filter(n=>n.match?.status===status).length;
  const accountLabel=l(personalAccount?.label??accounts.find(a=>a.id===account)?.label??account);
  const noticeCards=notices.filter(n=>filter==='all'||n.match?.status===filter||n.category===filter);

  if(sessionChecking)return <div className="login-page session-check"><div className="brand"><div className="brand-symbol"><GraduationCap size={23}/></div>UniAction</div><Loading lang={lang}/></div>;
  if(!account)return <div className="login-page">
    <header className="login-header"><div className="brand"><div className="brand-symbol"><GraduationCap size={23}/></div><div>UniAction<small>{t('유니액션 · 가칭','校园行动 · 暂定名')}</small></div></div>{languageButton}</header>
    <main className="login-main"><section className="login-intro"><span className="eyebrow">HANYANG UNIVERSITY</span><h1>{t('공지에서\n나의 다음 행동으로.','从校园通知，\n走向下一步行动。')}</h1><p>{t('내게 맞는 조건, 필요한 서류, 준비할 순서를 한곳에서 확인하세요.','查看与我相关的条件、所需材料和准备顺序。')}</p><div className="login-art"><div className="art-source"><FileText size={22}/><strong>{t('학교 공지','校园通知')}</strong><span>01 · 02 · 03</span><i/><i/><i/></div><ArrowRight className="art-arrow" size={28}/><div className="art-plan"><div><CheckCircle2 size={19}/>{t('조건과 근거 확인','条件与依据')}</div><div><ListChecks size={19}/>{t('서류 준비하기','准备材料')}</div><div><MessageCircle size={19}/>{t('담당자에게 문의','联系工作人员')}</div></div></div><div className="fiction-note"><ShieldCheck size={18}/><span>{t('데모 인물과 공지는 가상입니다. 개인 계정 정보는 이 컴퓨터에만 저장됩니다. 학교 공식 서비스가 아닌 프로토타입입니다.','演示人物和通知均为虚构。个人账号资料仅保存在此电脑。本原型并非学校正式服务。')}</span></div></section>
    <AuthPanel mode={authMode} setMode={mode=>{setError('');setAuthMode(mode);}} lang={lang} busy={busy} error={error} submit={submitAuth}><div className="account-options">{(accounts.length?accounts.filter(a=>a.id!=='other_staff'):[{id:'A',role:'student',school_id:'hanyang_demo',label:{ko:'학생 A',zh:'学生 A'}},{id:'B',role:'student',school_id:'hanyang_demo',label:{ko:'학생 B',zh:'学生 B'}},{id:'C',role:'student',school_id:'hanyang_demo',label:{ko:'학생 C',zh:'学生 C'}},{id:'staff',role:'staff',school_id:'hanyang_demo',label:{ko:'국제교류 담당자',zh:'国际交流工作人员'}}]).map(a=><button data-testid={"account-"+a.id} className="account-option" key={a.id} disabled={busy} onClick={()=>login(a.id)}><span className={`avatar ${a.role==='staff'?'staff-avatar':''}`}>{a.role==='staff'?<ShieldCheck size={21}/>:a.id}</span><span><strong>{l(a.label)}</strong><small>{a.id==='A'?t('학부 2학년 · 학점 입력 완료','本科二年级 · 已填写 GPA'):a.id==='B'?t('석사 1학기 · 경영 전공','硕士第一学期 · 商科'):a.id==='C'?t('학부 2학년 · 추가 정보 필요','本科二年级 · 需补充信息'):t('공지 검토 · 문의 처리','审核通知 · 处理协助')}</small></span><ArrowRight size={18}/></button>)}</div><p className="microcopy"><LockKeyhole size={14}/>{t('미리 정한 데모 인증입니다. 학교 SSO가 아닙니다.','预设演示认证，不是学校 SSO。')}</p></AuthPanel></main>
    <footer className="login-footer"><span>{t('고정 데모 데이터','固定演示数据')}</span><span>2026-10-07 10:00 · Asia/Seoul</span><span>{t('상표 등록을 주장하지 않는 가칭','名称暂定，不宣称已注册商标')}</span></footer>
  </div>;

  return <div className="app-shell"><aside className="sidebar"><div className="brand"><div className="brand-symbol"><GraduationCap size={22}/></div><div>UniAction<small>{t('유니액션 · 가칭','校园行动 · 暂定名')}</small></div></div><div className="workspace-label">{t('나의 학교','所属学校')}</div><div className="school-name">{t('한양대학교','汉阳大学')}<span>Hanyang University</span></div><nav aria-label={t('주 메뉴','主导航')}><button data-testid="nav-notices" className={page==='notices'?'active':''} onClick={()=>navigate('notices')}><LayoutDashboard size={19}/>{staff?t('공지 관리','通知管理'):t('나의 할 일','我的事项')}</button>{!staff&&<button data-testid="nav-profile" className={page==='profile'?'active':''} onClick={()=>navigate('profile')}><UserRound size={19}/>{t('학생 정보','学生资料')}</button>}{staff&&<button data-testid="nav-import" className={page==='import'||page==='review'?'active':''} onClick={()=>navigate('import')}><Upload size={19}/>{t('공지 가져오기','导入通知')}</button>}<button data-testid="nav-cases" className={page==='cases'?'active':''} onClick={()=>navigate('cases')}><MessageCircle size={19}/>{staff?t('도움 요청함','协助案例'):t('내 문의','我的协助')}{cases.length>0&&<span className="nav-count">{cases.length}</span>}</button></nav><div className="sidebar-bottom"><div className="demo-note"><Sparkles size={18}/><strong>{isDemo?t('고정 데모 환경','固定演示环境'):t('나의 로컬 계정','我的本地账号')}</strong><span>{isDemo?t('데모 인물 · 가상 공지','演示人物 · 虚构通知'):t('개인 정보는 이 컴퓨터에 저장','个人资料保存在此电脑')}</span><small>2026.10.07 · 10:00 KST</small></div><button data-testid="account-switch" disabled={busy} className="account-current" onClick={()=>login('')}><span className="avatar small">{staff?<ShieldCheck size={16}/>:personalAccount?<UserRound size={16}/>:account}</span><span><strong>{accountLabel}</strong><small>{t('계정 전환','切换账号')}</small></span><LogOut size={16}/></button>{personalAccount&&<button data-testid="logout" className="personal-logout" disabled={busy} onClick={()=>login('')}><LogOut size={15}/>{t('로그아웃','退出登录')}</button>}</div></aside>
    <div className="main-area"><header className="topbar"><span className="topbar-breadcrumb">{staff?t('행정 워크스페이스','工作人员空间'):t('학생 워크스페이스','学生空间')}<span>/</span>{selected?t('공지 상세','通知详情'):page==='profile'?t('학생 정보','学生资料'):page==='cases'?t('도움 요청','协助案例'):page==='import'?t('공지 가져오기','导入通知'):page==='review'?t('공지 검토','审核通知'):t('공지와 실행계획','通知与行动清单')}</span><div className="topbar-actions"><span className="demo-pill"><span/>{isDemo?t('데모','演示'):t('내 계정','个人账号')}</span>{languageButton}</div></header><main className="content">
      <div className="environment-strip"><Clock3 size={15}/><span>{t('고정 시각','固定时间')} {dateLabel(health.demo_time??'2026-10-07T10:00:00+09:00',lang)}</span><span className="environment-mode">{health.mode==='real_ai'?t('실제 AI 모드 · 공지마다 추출 방식 확인','真实 AI 模式 · 请查看各通知提取方式'):t('고정 데모 데이터 · 실제 AI 추출 아님','固定演示数据 · 非真实 AI 提取')}</span></div>
      {error&&<div className="alert error" role="alert"><X size={18}/><div><strong>{t('요청을 완료하지 못했습니다','请求未完成')}</strong><p>{error}</p></div><button aria-label={t('닫기','关闭')} onClick={()=>setError('')}><X size={16}/></button></div>}
      {feedback&&<div className="alert success" role="status"><CheckCircle2 size={18}/>{feedback}<button aria-label={t('닫기','关闭')} onClick={()=>setFeedback('')}><X size={16}/></button></div>}
      {selected&&detail?<NoticeDetail detail={detail} account={account} lang={lang} tab={detailTab} setTab={setDetailTab} busy={busy} run={run} navigate={navigate} openEditor={openEditor} back={()=>{setSelected(null);setDetail(null);}}/>:selected?<Loading lang={lang}/>:page==='profile'&&profile?<ProfilePanel profile={profile} setProfile={setProfile} isDemo={isDemo} needsGpa={notices.some(n=>n.id==='N1'&&n.match?.status!=='conditions_not_met')} lang={lang} busy={busy} save={()=>run(()=>api(account,'/profile','PUT',profile),t('정보를 저장하고 공지 조건을 다시 확인했습니다.','资料已保存，并重新匹配通知条件。'))}/>:page==='cases'?<CasesPanel cases={cases} account={account} lang={lang} busy={busy} run={run} openNotice={openNotice}/>:page==='import'?<>
        <PageTitle eyebrow="STAFF · NOTICE INTAKE" title={t('공지 가져오기','导入通知')} description={t('원문을 보존하고 중요한 조건을 검토한 뒤 게시합니다.','保留原文，审核重要条件后发布。')}/><div className="two-column"><section className="panel"><div className="section-heading"><Upload size={20}/><h2>{t('원문 입력','输入原文')}</h2></div><Field title={t('가상 공지 선택','选择虚构通知')}><select data-testid="source-selector" value="" onChange={e=>{const source=sources.find(s=>s.id===e.target.value);if(source){setSourceText(source.source_text);setSourceUrl('https://demo.invalid/hanyang/'+source.id);}}}><option value="">{t('직접 입력 또는 데모 원문 선택','直接输入或选择演示原文')}</option>{sources.map(source=><option key={source.id} value={source.id}>{source.id} · {l(source.title)}</option>)}</select></Field><Field title={t('공지 원문','通知原文')} hint={t('데모 추출은 정해진 5개 공지 및 N1 2차 원문 전체만 인식합니다.','演示提取只识别五则完整固定通知及 N1 第二版本。')}><textarea data-testid="source-text" className="source-input" value={sourceText} onChange={e=>setSourceText(e.target.value)} rows={12} placeholder={t('공지 전체 원문을 붙여 넣으세요.','粘贴完整通知原文。')}/></Field><Field title={t('원문 링크','原文链接')}><input value={sourceUrl} onChange={e=>setSourceUrl(e.target.value)} placeholder="https://demo.example.edu/…"/></Field><Field title={t('추출 모드','提取模式')}><select value={extractMode} onChange={e=>setExtractMode(e.target.value)}><option value="demo">{t('고정 데모 데이터','固定演示数据')}</option><option value="real">{t('실제 AI · 서버 API 설정 필요','真实 AI · 需要服务端 API 配置')}</option></select></Field><button data-testid="extract-draft" className="primary" disabled={busy||!sourceText.trim()} onClick={()=>run(async()=>{const draft=await api<Notice>(account,'/staff/import','POST',{source_text:sourceText,source_url:sourceUrl,mode:extractMode});setStaffDraft(draft);setStaffVersion(draft.version);setEditor(JSON.stringify(draft,null,2));setPage('review');},t('검토용 초안을 생성했습니다. 아직 학생 판단에 사용되지 않습니다.','已生成待审核草稿，尚未用于学生正式条件判断。'))}><Sparkles size={17}/>{busy?t('처리 중…','处理中…'):t('검토용 초안 생성','生成待审核草稿')}</button></section><section className="panel guide-panel"><span className="eyebrow">HUMAN REVIEW</span><h2>{t('게시 전, 근거부터.','发布之前，核对依据。')}</h2><p>{t('조건 검토는 학생 신청을 접수하거나 승인하는 행위가 아닙니다.','通知条件审核不等于受理或批准学生申请。')}</p><ol className="step-list"><li><span>1</span><div><strong>{t('원문과 조건 대조','核对原文与条件')}</strong><p>{t('조건·서류·날짜마다 정확한 원문 근거가 있어야 합니다.','条件、材料和日期均须有准确的原文依据。')}</p></div></li><li><span>2</span><div><strong>{t('모호한 표현 표시','标记模糊内容')}</strong><p>{t('TOPIK 기준이 없으면 새 기준을 만들지 않습니다.','没有 TOPIK 门槛时，不擅自添加。')}</p></div></li><li><span>3</span><div><strong>{t('검토 후 승인','审核后批准通知')}</strong><p>{t('새 버전도 다시 검토합니다. 승인 전 기존 버전을 유지합니다.','新版本也要重新审核。审核前保留已批准版本。')}</p></div></li></ol><div className="boundary-note"><LockKeyhole size={18}/><div><strong>{t('실제 AI 연결','真实 AI 接入')}</strong><p>{t('API 키가 없거나 응답에 문제가 있으면 초안은 게시되지 않습니다. 오류를 확인하고 수동 초안을 작성할 수 있습니다.','无 API 密钥或返回异常时，不发布草稿。可以检查错误并手动补充草稿。')}</p></div></div><button className="secondary" onClick={createManual}><Plus size={16}/>{t('수동 초안 작성','手动填写草稿')}</button></section></div>
      </>:page==='review'?<><PageTitle eyebrow="STAFF · NOTICE REVIEW" title={t('초안 검토와 편집','草稿审核与编辑')} description={t('중요 필드를 원문과 대조하세요. 승인 전에는 학생의 공식 조건 판단에 사용되지 않습니다.','请将重要字段与原文核对。批准前不用于学生正式条件结论。')}/><div className="review-layout"><section className="panel"><div className="section-heading"><FileText size={20}/><h2>{t('원문 보존','保留原文')}</h2>{staffDraft&&<Badge status={staffDraft.publication_status} lang={lang}/>}</div><pre className="source-text">{staffDraft?.source_text||sourceText||t('편집기에 원문을 입력하세요.','请在编辑器中填写原文。')}</pre>{staffDraft&&<><div className="review-summary"><span>{t('추출 방식','提取方式')}: {staffDraft.extraction_mode==='real_ai'?t('실제 AI 초안','真实 AI 草稿'):staffDraft.extraction_mode==='manual'?t('수동 초안','人工草稿'):t('고정 데모 데이터','固定演示数据')}</span><span>{t('버전','版本')} {staffVersion} · {staffDraft.id}</span></div><p className="microcopy">{t('신청 조건 검토이며, 학생 신청 결과 승인과 별개입니다.','这是通知条件审核，与学生申请结果批准相互独立。')}</p></>}</section><section className="panel"><div className="section-heading"><FileCheck2 size={20}/><h2>{t('구조화 필드 편집','编辑结构化字段')}</h2></div><p className="editor-hint">{t('조건·서류·마감·연락처·근거를 수정할 수 있습니다. 규칙과 필드는 서버에서 허용 목록으로 검증합니다.','可修改条件、材料、截止、联系人和依据。规则与字段由服务端按白名单校验。')}</p><textarea aria-label={t('구조화 초안 JSON 편집','编辑结构化草稿 JSON')} className="json-editor" spellCheck={false} value={editor} onChange={e=>setEditor(e.target.value)} rows={25}/><div className="button-row"><button className="secondary" disabled={busy} onClick={()=>run(async()=>{const body=JSON.parse(editor);const draft=staffDraft?await api<Notice>(account,`/staff/notices/${staffDraft.id}/versions/${staffVersion}`,'PUT',body):await api<Notice>(account,'/staff/manual','POST',body);setStaffDraft(draft);setStaffVersion(draft.version);setEditor(JSON.stringify(draft,null,2));},t('초안을 저장했습니다.','草稿已保存。'))}><Check size={16}/>{t('초안 저장','保存草稿')}</button><button className="secondary" disabled={busy||!staffDraft||staffDraft.publication_status==='approved'} onClick={()=>run(async()=>{const draft=await api<Notice>(account,`/staff/notices/${staffDraft!.id}/versions/${staffVersion}/review`,'POST');setStaffDraft(draft);setEditor(JSON.stringify(draft,null,2));},t('검토 중으로 변경했습니다.','已进入审核状态。'))}>{t('검토 시작','开始审核')}</button><button data-testid="approve-version" className="primary" disabled={busy||!staffDraft||staffDraft.publication_status==='approved'} onClick={()=>run(async()=>{await api(account,`/staff/notices/${staffDraft!.id}/versions/${staffVersion}`,'PUT',JSON.parse(editor));await api(account,`/staff/notices/${staffDraft!.id}/versions/${staffVersion}/review`,'POST');const draft=await api<Notice>(account,`/staff/notices/${staffDraft!.id}/versions/${staffVersion}/approve`,'POST');setStaffDraft(draft);setEditor(JSON.stringify(draft,null,2));},t('이 공지 버전을 승인했습니다. 관련 과제가 갱신됩니다.','已批准这个通知版本，相关任务将更新。'))}><ShieldCheck size={16}/>{t('검토 완료 · 버전 승인','审核完成 · 批准版本')}</button></div></section></div></>:<>
        <PageTitle eyebrow={staff?'STAFF · NOTICE DESK':'MY CAMPUS · NEXT STEPS'} title={staff?t('공지 관리','通知管理'):t(`${accountLabel}, 준비할 일을 확인하세요`,`${accountLabel}，查看需要准备的事项`)} description={staff?t('조건·원문·버전을 검토하고 학생의 다음 행동을 돕습니다.','审核条件、原文和版本，帮助学生明确下一步。'):t('내 정보로 조건을 확인하고, 필요한 서류부터 차근차근 준비하세요.','根据我的资料核对条件，从所需材料开始准备。')} action={<button className="secondary small-button" onClick={()=>load()} disabled={loading||busy}><RefreshCw size={15}/>{t('새로고침','刷新')}</button>}/>
        {!staff&&<div className="stats-grid"><Stat number={noticeCounts('conditions_met')} title={t('조건 충족','条件满足')} description={t('명확한 조건에 해당','满足明确条件')} icon={<CheckCircle2 size={23}/>} tone="green"/><Stat number={noticeCounts('missing_information')} title={t('추가 정보 필요','需要补充信息')} description={t('관련 정보만 보완','仅补充相关信息')} icon={<HelpCircle size={23}/>} tone="amber"/><Stat number={noticeCounts('needs_staff_review')} title={t('담당자 확인','工作人员确认')} description={t('모호한 조건을 문의','确认模糊条件')} icon={<MessageCircle size={23}/>} tone="purple"/></div>}
        {!staff&&<div className="profile-strip"><UserRound size={18}/><span>{profile?`${valueLabel(profile.program_type,lang)} · ${valueLabel(profile.department_id,lang)} · ${profile.semester??'—'}${t('학기','学期')}`:t('학생 정보 확인','查看学生资料')}</span><button onClick={()=>navigate('profile')}>{t('정보 수정','修改资料')}<ArrowRight size={14}/></button></div>}
        <div className="list-toolbar"><h2>{staff?t('학교 공지','学校通知'):t('나와 관련된 공지','与我相关的通知')}<span>{notices.length}</span></h2><label className="sr-only" htmlFor="notice-filter">{t('공지 필터','通知筛选')}</label><select id="notice-filter" value={filter} onChange={e=>setFilter(e.target.value)}><option value="all">{t('전체 공지','全部通知')}</option>{!staff&&(['conditions_met','missing_information','needs_staff_review','conditions_not_met'] as MatchStatus[]).map(s=><option key={s} value={s}>{label(s,lang)}</option>)}<option value="scholarship">{t('장학금','奖学金')}</option><option value="dormitory">{t('기숙사','宿舍')}</option><option value="activity">{t('교내 활동','校内活动')}</option></select></div>
        {loading&&!notices.length?<Loading lang={lang}/>:!noticeCards.length?<Empty>{t('표시할 공지가 없습니다. 필터를 바꾸거나 다시 불러오세요.','暂无通知，请调整筛选或重新加载。')}</Empty>:<div className="notice-grid">{noticeCards.map(notice=><button data-testid={"notice-"+notice.id} className="notice-card" key={notice.id} onClick={()=>openNotice(notice.id,staff?'evidence':'tasks')}><div className="card-top"><span className={`category category-${notice.category}`}>{categoryLabel(notice.category,lang)}</span><span className="notice-id">{notice.id} · v{notice.version}</span></div><h3>{l(notice.title)}</h3><div className="notice-badges">{notice.match?<Badge status={notice.match.status} lang={lang}/>:<Badge status={notice.publication_status} lang={lang}/>}</div><div className="card-deadline"><Clock3 size={15}/><span>{dateLabel(notice.official_deadline,lang)}</span></div><div className="card-footer"><span>{notice.application_state?label(applicationStatus(notice.application_state),lang):t('검토 상태 확인','查看审核状态')}</span><span>{t('상세 보기','查看详情')}<ArrowRight size={15}/></span></div></button>)}</div>}
        {staff&&<div className="reset-panel"><div><strong>{t('시연을 처음부터 다시 시작','从头重新演示')}</strong><p>{t('가상 학생 정보, 진행, 문의 및 공지 버전을 초기 상태로 되돌립니다.','将虚构资料、进度、案例和通知版本恢复到初始状态。')}</p></div><button data-testid="demo-reset" className="secondary" disabled={busy} onClick={()=>run(()=>api(account,'/demo/reset','POST'),t('가상 데모 데이터를 초기화했습니다.','虚构演示数据已重置。'))}><RefreshCw size={16}/>{t('데모 초기화','重置演示')}</button></div>}
      </>}
    </main><footer className="app-footer">{t('데모 인물과 공지는 가상 · 개인 정보는 본 기기에 저장 · 학교 접수/선발은 별도 확인','演示人物和通知虚构 · 个人资料保存在此电脑 · 最终受理与选拔由学校确认')}</footer></div></div>;
}

function PageTitle({eyebrow,title,description,action}:{eyebrow:string;title:string;description:string;action?:ReactNode}){return <div className="page-title"><div><span className="eyebrow">{eyebrow}</span><h1>{title}</h1><p>{description}</p></div>{action}</div>;}
function Stat({number,title,description,icon,tone}:{number:number;title:string;description:string;icon:ReactNode;tone:string}){return <div className={`stat-card ${tone}`}><span className="stat-icon">{icon}</span><div><span>{title}</span><strong>{number}<small>{description}</small></strong></div></div>;}

type Run=(action:()=>Promise<unknown>,success?:string)=>Promise<void>;
function NoticeDetail({detail,account,lang,tab,setTab,busy,run,navigate,openEditor,back}:{detail:Detail;account:string;lang:Lang;tab:string;setTab:(tab:string)=>void;busy:boolean;run:Run;navigate:(target:string)=>void;openEditor:(notice:Notice,version?:number)=>Promise<void>;back:()=>void}){
  const {notice,match,tasks}=detail;const staff=account==='staff'||account==='other_staff';const t=(ko:string,zh:string)=>tr(lang,ko,zh);const l=(v:unknown)=>localize(v,lang);
  const [message,setMessage]=useState('');const [scope,setScope]=useState<Scope>('case_only');const [versionNotice,setVersionNotice]=useState<Notice|null>(null);
  const done=tasks.filter(task=>task.status==='done').length;const officialLink=notice.application_link_type==='official';
  const evidenceEntries=Array.isArray(notice.evidence)?notice.evidence:Object.values(notice.evidence??{});
  const submissionStatus=typeof detail.submission_status==='string'?detail.submission_status:detail.submission_status?.status;
  const contact=notice.office_contact;
  return <><button className="back-button" onClick={back}><ArrowLeft size={16}/>{t('공지 목록','返回通知列表')}</button><div className="notice-heading"><div><div className="card-top"><span className={`category category-${notice.category}`}>{categoryLabel(notice.category,lang)}</span><span className="notice-id">{notice.id} · {t('공지 버전','通知版本')} {notice.version}</span></div><h1>{l(notice.title)}</h1><div className="notice-badges">{match&&<Badge status={match.status} lang={lang}/>}<Badge status={notice.publication_status} lang={lang}/><span className="window-state"><Clock3 size={14}/>{label(applicationStatus(detail.application_state),lang)}</span></div></div><div className="deadline-box"><span>{t('학교 공식 마감','学校正式截止')}</span><strong>{dateLabel(notice.official_deadline,lang)}</strong></div></div>
    {notice.version>1&&<div className="update-banner"><Bell size={20}/><div><strong>{t('공지 내용이 변경되었습니다','通知内容已更新')} · v{notice.version}</strong><p>{l(notice.change_summary)}</p></div><button onClick={()=>setTab('versions')}>{t('변경 확인','查看变化')}<ArrowRight size={14}/></button></div>}
    {match?.status==='conditions_met'&&<p className="qualification-note"><ShieldCheck size={17}/>{t('현재 제공한 정보로 공지의 명확한 조건을 충족합니다. 최종 접수, 자격 확인 및 선발 결과는 학교가 확인합니다.','按当前提供的信息满足通知明确条件。最终受理、资格核验及选拔结果由学校确认。')}</p>}
    {match?.status==='missing_information'&&<div className="missing-banner"><HelpCircle size={20}/><div><strong>{t('조건 확인에 필요한 정보','判断条件还需这些信息')}</strong><p>{match.missing_fields.map(field=>fieldLabel(field,lang)).join(' · ')}</p></div><button className="secondary small-button" onClick={()=>navigate('profile')}>{t('정보 보완','补充资料')}<ArrowRight size={14}/></button></div>}
    <div className="tabs" role="tablist">{detailTabs.filter(([key])=>!staff||key==='evidence'||key==='versions').map(([key,ko,zh])=><button data-testid={"detail-tab-"+key} key={key} role="tab" aria-selected={tab===key} onClick={()=>setTab(key)} className={tab===key?'selected':''}>{t(ko,zh)}{key==='tasks'&&tasks.length>0&&<span>{tasks.length}</span>}</button>)}{staff&&<button className="tab-edit" onClick={()=>openEditor(notice)}><FileCheck2 size={16}/>{t('검토 / 편집','审核 / 编辑')}</button>}</div>
    {tab==='tasks'&&<div className="detail-grid"><section className="panel"><div className="section-heading"><ListChecks size={21}/><h2>{t('나의 실행계획','我的行动清单')}</h2><span className="muted">{done}/{tasks.length} {t('완료','完成')}</span></div>{tasks.length?<><div className="progress-track"><span style={{width:`${done/tasks.length*100}%`}}/></div><div className="tasks-list">{tasks.map((task,index)=><TaskItem key={task.id} task={task} tasks={tasks} index={index} lang={lang} busy={busy} update={status=>run(()=>api(account,`/tasks/${task.id}`,'PATCH',{status}),t('진행 상태를 저장했습니다.','进度已保存。'))}/>)}</div></>:<><Empty>{match?.status==='conditions_not_met'?t('현재 명확한 조건에 해당하지 않습니다. 조건 근거를 확인하세요.','当前不满足明确条件，请查看条件依据。'):t('학교 필수 서류와 준비 제안을 실행계획으로 정리합니다.','将学校必需材料和系统准备建议整理为行动清单。')}</Empty><button data-testid="generate-tasks" className="primary" disabled={busy||notice.publication_status!=='approved'||match?.status==='conditions_not_met'} onClick={()=>run(()=>api(account,`/notices/${notice.id}/tasks`,'POST'),t('실행계획을 준비했습니다. 기존 과제는 중복 생성되지 않습니다.','行动清单已生成，同一任务不会重复创建。'))}><Plus size={17}/>{t('나의 실행계획 만들기','生成我的行动清单')}</button></>}
      {tasks.length>0&&<div className="submission-panel"><FileCheck2 size={20}/><div><strong>{submissionStatus==='self_reported_submitted'?t('내 제출 완료 기록','我已提交的自报记录'):t('공식 절차로 제출했다면','如果已通过官方流程提交')}</strong><p>{t('이 버튼은 학생 본인의 기록입니다. 학교 수신·접수·승인이 확인된 상태가 아닙니다.','此按钮仅记录学生自报，不代表学校已收到、受理或批准。')}</p></div><button className="secondary" disabled={busy||submissionStatus==='self_reported_submitted'} onClick={()=>run(()=>api(account,`/notices/${notice.id}/submit`,'POST'),t('본인이 제출했다고 기록했습니다. 학교 확인은 별도입니다.','已记录学生自报提交，学校确认仍需另行核实。'))}><Check size={16}/>{submissionStatus==='self_reported_submitted'?t('제출했다고 기록됨','已记录自报提交'):t('내가 제출했다고 기록','记录我已提交')}</button></div>}</section><aside className="detail-aside"><section className="panel"><div className="section-heading"><FileText size={20}/><h2>{t('필수 서류','必需材料')}</h2></div>{notice.required_documents?.length?<ul className="document-list">{notice.required_documents.map(doc=><li key={doc.id}><FileText size={16}/><div><strong>{l(doc.title)}</strong><details><summary>{t('원문 근거','原文依据')}</summary><blockquote>{doc.evidence}</blockquote></details></div></li>)}</ul>:<p className="muted">{t('원문에 필수 제출 서류가 명시되지 않았습니다.','原文未列明必需提交材料。')}</p>}<p className="microcopy">{t('필수와 준비 제안을 구분합니다.','区分学校必需要求与准备建议。')}</p></section><section className="panel"><h2>{t('신청과 문의','办理与联系')}</h2><p className="muted">{t('시스템은 실제 신청을 자동 제출하지 않습니다.','系统不自动提交真实申请。')}</p>{notice.application_url&&<div className="application-link"><span className={`badge ${officialLink?'approved':'missing_information'}`}>{officialLink?t('공식 신청 링크','官方办理链接'):t('데모 자리표시 링크','演示占位链接')}</span><a href={notice.application_url} target="_blank" rel="noreferrer">{notice.application_url}<ArrowRight size={14}/></a>{!officialLink&&<small>{t('실제 신청에 사용할 수 없는 가상 링크입니다.','这是虚构链接，不用于真实申请。')}</small>}</div>}<div className="office-contact"><strong>{t('담당 부서','办理咨询部门')}</strong><p>{contact?l(contact.name):t('담당 부서 정보 확인 필요','需确认办理部门')}</p>{contact?.email&&<p>{t('이메일','邮箱')}: {contact.email}</p>}{contact?.phone&&<p>{t('전화','电话')}: {contact.phone}</p>}{contact?.is_demo&&<small>{t('데모 연락처 · 실제 문의 불가','演示联系方式 · 不发送真实咨询')}</small>}{contact?.evidence&&<details><summary>{t('연락처 원문 근거','联系人原文依据')}</summary><blockquote>{contact.evidence}</blockquote></details>}</div><button className="secondary full-width" onClick={()=>setTab('help')}><MessageCircle size={16}/>{t('이 공지에 도움 요청','请求此事项的协助')}</button></section></aside></div>}
    {tab==='evidence'&&<div className="detail-grid"><section className="panel"><div className="section-heading"><ShieldCheck size={21}/><h2>{t('어떤 조건을 확인했나요?','采用了哪些条件？')}</h2></div>{match?<><div className="condition-list">{match.reasons.map((reason,index)=><div className={`condition-row ${reason.result===true?'yes':reason.result===false?'no':'unsure'}`} key={index}><span className="condition-icon">{reason.result===true?<Check size={16}/>:reason.result===false?<X size={16}/>:<HelpCircle size={16}/>}</span><div><strong>{reason.field?fieldLabel(reason.field,lang):t('담당자 판단이 필요한 조건','需要工作人员确认的条件')}</strong><p>{t('내 정보','我的资料')}: {valueLabel(reason.actual,lang)} · {t('공지 기준','通知条件')}: {Array.isArray(reason.expected)?reason.expected.map(v=>valueLabel(v,lang)).join(' / '):reason.op==='needs_staff_review'?t('명확한 기준 없음 · 담당자 확인','无明确量化标准 · 工作人员确认'):valueLabel(reason.op==='is_true'?true:reason.op==='is_false'?false:reason.expected,lang)}</p><span className="reason-result">{reason.result===true?t('충족','满足'):reason.result===false?t('불충족','不满足'):t('추가 정보 / 담당자 확인 필요','需补充信息或工作人员确认')}</span>{reason.evidence&&<details open={reason.result!==true}><summary>{t('원문 근거 보기','查看原文依据')}</summary><blockquote>{reason.evidence}</blockquote></details>}{reason.message&&<p>{l(reason.message)}</p>}</div></div>)}</div>{match.needs_staff_review&&<div className="boundary-note"><MessageCircle size={19}/><div><strong>{t('담당자 확인이 필요합니다','需要工作人员确认')}</strong><p>{t('모호한 표현은 임의의 점수 기준으로 바꾸지 않습니다. 이 공지에 대해 문의할 수 있습니다.','不会把模糊描述转换成自行设定的分数门槛。您可以针对这个事项请求确认。')}</p><button className="text-button" onClick={()=>setTab('help')}>{t('도움 요청','请求协助')}<ArrowRight size={14}/></button></div></div>}</>:<><p className="muted">{t('학생의 개별 조건 결과는 승인된 공지에서만 표시됩니다.','学生个人条件结果仅基于已审核通知显示。')}</p><pre className="rule-preview">{JSON.stringify(notice.eligibility_rules,null,2)}</pre></>}
      {!!notice.ambiguities?.length&&<div className="ambiguities"><h3>{t('불명확하거나 확인할 내용','模糊或需要确认的内容')}</h3><ul>{notice.ambiguities.map((ambiguity,i)=><li key={i}>{l(ambiguity)}</li>)}</ul></div>}{evidenceEntries.length>0&&<details className="all-evidence"><summary>{t('추가 원문 근거','其他原文依据')}</summary>{evidenceEntries.map((item,index)=><blockquote key={index}>{l(item)}</blockquote>)}</details>}</section><section className="panel"><div className="section-heading"><FileText size={20}/><h2>{t('공지 원문','通知原文')}</h2><span className="badge draft">{t('가상 공지','虚构通知')}</span></div><pre className="source-text">{notice.source_text}</pre><div className="source-meta"><strong>{t('공지 데이터','通知数据')}</strong><span>{notice.extraction_mode==='real_ai'?t('실제 AI 초안 · 담당자 검토','真实 AI 草稿 · 工作人员审核'):notice.extraction_mode==='manual'?t('수동 작성','人工填写'):t('고정 데모 데이터','固定演示数据')}</span><strong>{t('원문 링크','原文链接')}</strong><a href={notice.source_url} target="_blank" rel="noreferrer">{notice.source_url}</a><small>{t('학교 공식 자료가 아닌 데모 자리표시 주소입니다.','这是演示占位地址，非真实学校资料。')}</small><strong>{t('공지 검토','通知审核')}</strong><span>{notice.reviewed_by??'—'} · {dateLabel(notice.reviewed_at,lang)}</span></div></section></div>}
    {tab==='versions'&&<section className="panel"><div className="section-heading"><RefreshCw size={21}/><h2>{t('공지 버전 이력','通知版本历史')}</h2></div><p className="muted">{t('새 버전은 다시 검토합니다. 승인 전에는 기존 결과를 유지하며, 관련 없는 진행은 보존합니다.','新版本需要重新审核。批准前保留原有正式结果，并保留不受影响的进度。')}</p><div className="versions-list">{detail.versions.map(version=><article className="version-card" key={version.version}><div><strong>v{version.version}</strong><Badge status={version.publication_status} lang={lang}/><span>{version.version===notice.version?t('현재 학생 기준','当前学生判断依据'):''}</span></div><p>{l(version.change_summary)}</p><div className="button-row"><button className="secondary small-button" onClick={()=>run(async()=>setVersionNotice(await api<Notice>(account,`/notices/${notice.id}/versions/${version.version}`)))}><FileText size={15}/>{t('이 버전 원문 보기','查看此版本原文')}</button>{staff&&<button className="secondary small-button" onClick={()=>openEditor(notice,version.version)}><FileCheck2 size={15}/>{t('이 버전 검토','审核此版本')}</button>}</div></article>)}</div>{versionNotice&&<div className="version-preview"><div className="section-heading"><h3>v{versionNotice.version} · {l(versionNotice.title)}</h3><button className="icon-button" aria-label={t('원문 닫기','关闭原文')} onClick={()=>setVersionNotice(null)}><X size={18}/></button></div><p>{l(versionNotice.change_summary)}</p><strong>{t('공식 마감','正式截止')}: {dateLabel(versionNotice.official_deadline,lang)}</strong><pre className="source-text">{versionNotice.source_text}</pre></div>}</section>}
    {tab==='help'&&<div className="two-column"><section className="panel"><div className="section-heading"><MessageCircle size={21}/><h2>{t('이 공지에 대해 도움 요청','请求此通知相关协助')}</h2></div><Field title={t('어떤 부분이 궁금한가요?','哪些部分需要帮助？')}><textarea data-testid="help-message" value={message} onChange={e=>setMessage(e.target.value)} rows={5} placeholder={t('예: 한국어 의사소통 조건을 어떻게 확인하나요?','例如：如何确认韩语沟通条件？')}/></Field><Field title={t('이 공지의 공유 범위','此通知的共享范围')}><select data-testid="help-scope" value={scope} onChange={e=>setScope(e.target.value as Scope)}>{(['case_only','tasks_and_cases','none'] as Scope[]).map(s=><option key={s} value={s}>{scopeLabel(s,lang)}</option>)}</select></Field><div className="sharing-preview"><LockKeyhole size={19}/><div><strong>{t('보내기 전 공유 내용 확인','发送前确认共享内容')}</strong><p>{scope==='none'?t('담당자에게 공유하지 않습니다. 아래 문의는 나의 기록으로만 저장됩니다.','不向工作人员共享。以下内容仅保存为我的记录。'):scope==='case_only'?t('이 공지, 내가 작성한 메시지, 데모 학생 식별자만 담당자에게 전달합니다.','仅共享此通知、我填写的消息和演示学生标识。'):t('이 공지, 내가 작성한 메시지와 이 공지의 관련 과제 진행을 담당자와 공유합니다.','共享此通知、我填写的消息及此通知相关任务的进度。')}</p><small>{t('학점, 전체 학생 정보, 다른 공지의 진행은 공유하지 않습니다.','不共享 GPA、完整个人资料或其他通知的任务进度。')}</small></div></div><button data-testid="send-help" className="primary" disabled={busy||!message.trim()} onClick={()=>run(async()=>{await api(account,'/cases','POST',{notice_id:notice.id,message,sharing_scope:scope});setMessage('');},scope==='none'?t('나의 비공개 문의 기록으로 저장했습니다.','已保存为我的私人案例记录。'):t('선택한 내용만 담당자에게 공유했습니다.','已将选定内容共享给工作人员。'))}><Send size={16}/>{scope==='none'?t('비공개로 기록','保存私人记录'):t('선택한 내용으로 도움 요청','按选定范围请求协助')}</button></section><section className="panel"><div className="section-heading"><ShieldCheck size={21}/><h2>{t('현재 접근 권한','当前访问授权')}</h2></div><p className="current-scope">{scopeLabel(detail.sharing_scope??'none',lang)}</p><p className="muted">{t('이 공지에 대한 후속 접근 권한은 언제든 변경할 수 있습니다. 철회 후 담당자는 이 공지의 사례나 진행을 다시 열 수 없습니다.','可随时修改此通知的后续访问权限。撤销后，工作人员不能再打开此通知的协助内容或进度。')}</p><Field title={t('후속 접근 범위 변경','修改后续访问范围')}><select data-testid="current-sharing" aria-label={t('후속 접근 범위 변경','修改后续访问范围')} value={detail.sharing_scope??'none'} disabled={busy} onChange={e=>{const nextScope=e.currentTarget.value as Scope;void run(()=>api(account,`/notices/${notice.id}/sharing`,'PUT',{sharing_scope:nextScope}),t('접근 범위를 변경했습니다.','访问授权已更新。'));}}>{(['none','case_only','tasks_and_cases'] as Scope[]).map(s=><option key={s} value={s}>{scopeLabel(s,lang)}</option>)}</select></Field><button data-testid="revoke-sharing" className="secondary" disabled={busy||detail.sharing_scope==='none'} onClick={()=>run(()=>api(account,`/notices/${notice.id}/sharing`,'PUT',{sharing_scope:'none'}),t('후속 접근 권한을 철회했습니다.','已撤销后续访问授权。'))}><LockKeyhole size={16}/>{t('후속 접근 권한 철회','撤销后续访问授权')}</button><div className="boundary-note"><HelpCircle size={18}/><p>{t('문의 처리 완료는 학생 신청의 성공을 뜻하지 않습니다. 메시지는 실제 이메일이나 외부 채팅으로 전송되지 않습니다.','协助处理完成不代表学生申请成功。消息不会发送到真实邮箱或外部聊天平台。')}</p></div></section></div>}
  </>;
}

function TaskItem({task,tasks,index,lang,busy,update}:{task:Task;tasks:Task[];index:number;lang:Lang;busy:boolean;update:(status:string)=>Promise<void>}){
  const t=(ko:string,zh:string)=>tr(lang,ko,zh);const required=task.required_or_suggested==='required';const dependencies=(task.depends_on??[]).map(id=>tasks.find(item=>item.id===id)).filter(Boolean) as Task[];
  return <article data-testid={"task-"+task.id} className={`task-item status-${task.status}`}><div className="task-number">{task.status==='done'?<Check size={18}/>:index+1}</div><div className="task-body"><div className="task-top"><span className={`requirement-tag ${required?'required':'suggested'}`}>{required?t('학교 필수','学校必需'):t('준비 제안','准备建议')}</span><Badge status={task.status} lang={lang}/></div><h3>{localize(task.title,lang)}</h3><p>{localize(task.description,lang)}</p><div className="task-dates">{task.official_due_at&&<span><Clock3 size={13}/>{t('공식 마감','正式截止')}: {dateLabel(task.official_due_at,lang)}</span>}{task.suggested_start_at&&<span>{t('조정 가능한 준비 시작 제안','可调整的建议准备日期')}: {dateLabel(task.suggested_start_at,lang)}</span>}</div>{dependencies.length>0&&<div className="task-dependencies"><ArrowRight size={13}/>{t('먼저 할 일','先完成')}: {dependencies.map(dep=>localize(dep.title,lang)).join(' → ')}</div>}{task.source_evidence&&<details><summary>{t('원문 근거','原文依据')}</summary><blockquote>{task.source_evidence}</blockquote></details>}<label className="task-status-control"><span>{t('내 진행','我的进度')}</span><select data-testid={"task-status-"+task.id} value={task.status} disabled={busy} onChange={e=>update(e.target.value)} aria-label={`${localize(task.title,lang)} ${t('진행 상태','进度状态')}`}>{['todo','in_progress','done','needs_help','requires_reconfirmation'].map(s=><option key={s} value={s}>{label(s,lang)}</option>)}</select></label>{task.status==='requires_reconfirmation'&&<p className="reconfirm-hint">{t('공지 변경으로 영향을 받았습니다. 새 근거와 날짜를 확인한 후 상태를 다시 선택하세요.','此任务受通知变更影响，请核对新依据和日期后重新选择状态。')}</p>}</div></article>;
}

function ProfilePanel({profile,setProfile,isDemo,needsGpa,lang,busy,save}:{profile:Profile;setProfile:(profile:Profile)=>void;isDemo:boolean;needsGpa:boolean;lang:Lang;busy:boolean;save:()=>Promise<void>}){
  const t=(ko:string,zh:string)=>tr(lang,ko,zh);function update(key:string,value:unknown){setProfile({...profile,[key]:value});}
  const select=(key:string,values:string[],optional=false)=><select data-testid={"profile-"+key} value={profile[key]==null?'':String(profile[key])} onChange={e=>update(key,e.target.value||null)}>{optional&&<option value="">{t('미입력 / 모름','未填写 / 不确定')}</option>}{values.map(value=><option key={value} value={value}>{valueLabel(value,lang)}</option>)}</select>;
  const numberInput=(key:string,max=20,step=1)=><input data-testid={"profile-"+key} type="number" min={0} max={max} step={step} value={profile[key]==null?'':String(profile[key])} onChange={e=>update(key,e.target.value===''?null:Number(e.target.value))}/>;
  const booleanInput=(key:string)=><select data-testid={"profile-"+key} value={profile[key]==null?'unknown':String(profile[key])} onChange={e=>update(key,e.target.value==='unknown'?null:e.target.value==='true')}><option value="unknown">{t('모름 / 미입력','不确定 / 未填写')}</option><option value="true">{t('예','是')}</option><option value="false">{t('아니요','否')}</option></select>;
  return <><PageTitle eyebrow="MY PROFILE · MINIMUM INFORMATION" title={t('조건 확인에 필요한 학생 정보','用于判断条件的学生资料')} description={t('관련 신청에 필요한 정보만 입력합니다. 수정한 정보로 다시 확인할 수 있습니다.','只填写相关申请所需信息，可修改资料并重新匹配。')}/><div className="profile-layout"><section className="panel"><div className="section-heading"><UserRound size={21}/><h2>{t('기본 정보','基础资料')}</h2></div><div className="fields-grid"><Field title={fieldLabel('school_id',lang)} hint={t('계정으로 결정되며 학교 범위 확인에 사용합니다.','由账号确定，用于确认所属学校范围。')}><input value={t('한양대학교','汉阳大学')} disabled/></Field><Field title={fieldLabel('program_type',lang)} hint={t('학위/과정별 신청 조건을 확인합니다.','用于核对学位或课程条件。')}>{select('program_type',['language','undergraduate','master','doctor'])}</Field><Field title={fieldLabel('enrollment_status',lang)} hint={t('재학 여부 조건을 확인합니다.','用于核对在读条件。')}>{select('enrollment_status',['enrolled','leave','graduated'])}</Field><Field title={fieldLabel('department_id',lang)} hint={t('학교 공통 전공 분류로 대상 여부를 확인합니다.','采用学校统一院系分类判断对象范围。')}>{select('department_id',['engineering','business','humanities'])}</Field><Field title={fieldLabel('year',lang)} hint={t('학년 제한이 있는 공지에 사용합니다.','用于设有年级限制的通知。')}>{numberInput('year')}</Field><Field title={fieldLabel('semester',lang)} hint={t('첫 학기 등 학기 조건을 확인합니다. 학년과 별개입니다.','用于第一学期等条件，与年级单独记录。')}>{numberInput('semester',30)}</Field><Field title={fieldLabel('international_student',lang)} hint={t('외국인 학생 대상 공지에 사용합니다.','用于判断外国学生专属通知。')}>{booleanInput('international_student')}</Field></div><details className="optional-profile"><summary><span>{t('관련 신청에 필요한 추가 정보','相关申请所需补充资料')}</span><ChevronDown size={16}/></summary><p className="muted">{t('장학금 N1에만 학점, 기숙사 N3에만 거주 정보를 사용합니다. 불확실한 항목은 모름으로 남길 수 있습니다.','仅 N1 奖学金使用 GPA、N3 宿舍续住使用住宿信息。不确定的字段可保留未知。')}</p><div className="fields-grid">{needsGpa&&<><Field title={fieldLabel('gpa_value',lang)} hint={t('N1 장학금 조건 확인용 · 선택 입력','用于 N1 奖学金条件 · 按需填写')}>{numberInput('gpa_value',5,0.01)}</Field><Field title={fieldLabel('gpa_scale',lang)} hint={t('4.3과 4.5는 자동 환산하지 않습니다.','4.3 与 4.5 满分制不自动换算。')}>{numberInput('gpa_scale',5,0.1)}</Field><Field title={fieldLabel('gpa_period',lang)} hint={t('N1은 직전 학기 성적을 요구합니다.','N1 要求上一学期成绩。')}>{select('gpa_period',['previous_semester','cumulative','current_semester'],true)}</Field></>}<Field title={fieldLabel('current_dorm_resident',lang)} hint={t('N3 기숙사 연장 조건 확인용','用于 N3 宿舍续住条件')}>{booleanInput('current_dorm_resident')}</Field></div></details><div className="button-row"><button data-testid="save-profile" className="primary" disabled={busy} onClick={save}><RefreshCw size={17}/>{busy?t('저장 중…','保存中…'):t('저장하고 조건 다시 확인','保存并重新匹配')}</button></div></section><aside className="panel profile-purpose"><LockKeyhole size={28}/><h2>{t('필요한 정보만.','仅需要的资料。')}</h2><p>{t('학교 규정에 해당하는지 확인하기 위한 최소 정보입니다.','这些是核对学校通知条件所需的最少信息。')}</p><ul><li>{t('미입력과 모름은 “아니요”로 바꾸지 않습니다.','空值与不确定不会被转换为“否”。')}</li><li>{t('학점의 만점이나 기간이 다르면 담당자 확인을 요청합니다.','GPA 满分制或期间不同则要求人工确认。')}</li><li>{t('여권번호, 외국인등록번호, 은행, 건강, 전체 주소를 받지 않습니다.','不收集护照号码、外国人登录证号码、银行、健康资料或完整住址。')}</li><li>{t('담당자에게 학점 등 전체 개인 정보는 공유하지 않습니다.','工作人员不能读取 GPA 等完整个人字段。')}</li></ul><div className="fiction-note"><ShieldCheck size={18}/><span>{isDemo?t('이 화면은 가상 데모 계정 정보입니다.','当前页面使用虚构演示账号资料。'):t('내가 입력한 개인 정보는 이 컴퓨터의 로컬 서비스에 저장됩니다.','我填写的个人资料保存在此电脑的本地服务中。')}</span></div></aside></div></>;
}

function CasesPanel({cases,account,lang,busy,run,openNotice}:{cases:HelpCase[];account:string;lang:Lang;busy:boolean;run:Run;openNotice:(id:string,tab?:string)=>void}){
  const staff=account==='staff'||account==='other_staff';const t=(ko:string,zh:string)=>tr(lang,ko,zh);
  return <><PageTitle eyebrow={staff?'STAFF · AUTHORIZED CASES':'MY SUPPORT · SHARING'} title={staff?t('학생 도움 요청','学生协助案例'):t('내 도움 요청','我的协助案例')} description={staff?t('학생이 허용한 문의만 표시됩니다. 관련 과제는 추가 승인 범위에서만 볼 수 있습니다.','仅显示学生授权的案例。相关任务仅在明确授权范围内可见。'):t('내가 보낸 내용과 담당자 답변을 확인하고 접근 권한을 바꿀 수 있습니다.','查看已发送内容和工作人员回复，可修改后续访问授权。')}/>{!cases.length?<Empty>{staff?t('현재 볼 수 있는 승인된 문의가 없습니다. 학생 계정에서 공유 범위를 정해 문의하세요.','暂无获授权的案例。可切换学生账号，选择共享范围并请求协助。'):t('아직 도움 요청이 없습니다. 공지 상세에서 필요한 내용을 문의하세요.','尚无协助案例，请在通知详情中提交需要帮助的内容。')}</Empty>:<div className="cases-grid">{cases.map(item=><CaseCard key={item.id} item={item} account={account} lang={lang} busy={busy} run={run} openNotice={openNotice}/>)}</div>}<p className="case-boundary"><ShieldCheck size={17}/>{t('도움 요청의 처리 상태는 학교의 신청 접수·승인 결과와 별개입니다.','协助处理状态与学校申请受理、批准结果相互独立。')}</p></>;
}

function CaseCard({item,account,lang,busy,run,openNotice}:{item:HelpCase;account:string;lang:Lang;busy:boolean;run:Run;openNotice:(id:string,tab?:string)=>void}){
  const staff=account==='staff'||account==='other_staff';const t=(ko:string,zh:string)=>tr(lang,ko,zh);const [response,setResponse]=useState(item.response??'');const [caseStatus,setCaseStatus]=useState(item.status);const [sharedTasks,setSharedTasks]=useState<Task[]|null>(null);
  useEffect(()=>{setResponse(item.response??'');setCaseStatus(item.status);setSharedTasks(null);},[item.id,item.response,item.status,item.current_sharing_scope,item.sharing_scope]);
  return <article className="panel case-card"><div className="case-header"><span className="case-icon"><MessageCircle size={19}/></span><div><h2>{item.notice_id} · {staff?`${t('학생','学生')} ${item.student_id}`:t('내 문의','我的案例')}</h2><span>{dateLabel(item.created_at,lang)}</span></div><Badge status={item.status==='open'?'case_open':item.status} lang={lang}/></div><div className="case-message">{item.message}</div><p className="case-scope"><LockKeyhole size={14}/>{scopeLabel(item.current_sharing_scope??item.sharing_scope??'none',lang)}</p>{staff?<><Field title={t('담당자 답변','工作人员回复')}><textarea value={response} onChange={e=>setResponse(e.target.value)} rows={3} placeholder={t('조건 확인 방법이나 다음 절차를 안내하세요.','说明条件确认方式或下一步流程。')}/></Field><Field title={t('문의 처리 상태','协助处理状态')}><select value={caseStatus} onChange={e=>setCaseStatus(e.target.value)}>{['open','in_progress','resolved'].map(s=><option value={s} key={s}>{s==='open'?t('접수된 문의','待处理案例'):label(s,lang)}</option>)}</select></Field><div className="button-row"><button className="primary" disabled={busy} onClick={()=>run(()=>api(account,`/cases/${item.id}`,'PATCH',{status:caseStatus,response}),t('문의 답변을 저장했습니다. 신청 성공을 의미하지 않습니다.','已保存协助回复，不代表申请成功。'))}><Check size={16}/>{t('답변과 상태 저장','保存回复与状态')}</button>{(item.current_sharing_scope??item.sharing_scope)==='tasks_and_cases'&&<button className="secondary" disabled={busy} onClick={()=>run(async()=>{const result=await api<Task[]|{tasks:Task[]}>(account,`/staff/students/${item.student_id}/notices/${item.notice_id}/tasks`);setSharedTasks(Array.isArray(result)?result:result.tasks);})}><ListChecks size={16}/>{t('허용된 과제 보기','查看授权任务')}</button>}</div>{sharedTasks&&<div className="shared-tasks"><strong>{t('이 공지의 관련 진행만','仅此通知相关进度')}</strong>{sharedTasks.length?sharedTasks.map(task=><div key={task.id}><span>{localize(task.title,lang)}</span><Badge status={task.status} lang={lang}/></div>):<p>{t('아직 생성된 과제가 없습니다.','尚未生成任务。')}</p>}</div>}</>:<>{item.response&&<div className="case-response"><strong>{t('담당자 답변','工作人员回复')}</strong><p>{item.response}</p></div>}<button className="secondary" onClick={()=>openNotice(item.notice_id,'help')}><LockKeyhole size={16}/>{t('공유 범위 확인 / 철회','查看 / 撤销共享授权')}<ArrowRight size={14}/></button></>}</article>;
}
